    +/**
    + * FactChecker contract class for interacting with the GenLayer AI Fact-Checker prediction contract
    + */
    +class FactChecker {
    +  private contractAddress: `0x${string}`;
    +  private client: any;
    +  private studioUrl?: string;
    +
    +  constructor(
    +    contractAddress: string,
    +    address?: string | null,
    +    studioUrl?: string
