    +  ): Promise<FeePresetEstimate | undefined> {
    +    return estimateWriteFeePreset(
    +      this.client,
    +      {
    +        address: this.contractAddress,
    +        functionName: "place_stake",
    +        args: [BigInt(claimId), vote],
    +      },
    +      level
    +    );
    +  }
    +
    +  async estimateResolveClaimFees(
